import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Grundposition der Realität als Basis","description":"","frontmatter":{},"headers":[],"relativePath":"de/09-现实为基根本立场.md","filePath":"de/09-现实为基根本立场.md","lastUpdated":null}'),s={name:"de/09-现实为基根本立场.md"};function a(d,e,l,u,o,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="grundposition-der-realitat-als-basis" tabindex="-1">Grundposition der Realität als Basis <a class="header-anchor" href="#grundposition-der-realitat-als-basis" aria-label="Permalink to &quot;Grundposition der Realität als Basis&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>09</td></tr><tr><td>Modul</td><td>Allgemeine Grundsätze und Kerneinstellungen</td></tr><tr><td>Schlüsselwörter</td><td>Realität als Basis, Einzige Realität, Grenze der Fiktion, Aktualisierung der Gesetze, Praktische Verifikation</td></tr></tbody></table><h2 id="i-grunddefinition-der-realitat-als-basis" tabindex="-1">I. Grunddefinition der Realität als Basis <a class="header-anchor" href="#i-grunddefinition-der-realitat-als-basis" aria-label="Permalink to &quot;I. Grunddefinition der Realität als Basis&quot;">​</a></h2><p>Realität als Basis ist die grundlegende erkenntnistheoretische Position und das methodologische Prinzip der Anker-Symbiotischen Zivilisation. Es bedeutet, dass alle theoretischen Konstruktionen, institutionellen Entwürfe, Kultivierungspraktiken und technologischen Innovationen der Zivilisation die reale Welt als einzige reale Grundlage und letztes Verifikationskriterium annehmen müssen. &quot;Realität&quot; bezieht sich auf die materiell existierende materielle Welt und Energiewelt, die wahrgenommen, gemessen und verifiziert werden kann, und ist der reale Ort des Überlebens und der Evolution des Lebens.</p><p>Die Position der Realität als Basis enthält drei Bedeutungsebenen: Erstens ist die reale Welt die einzige reale Welt, und fiktive Welten (einschließlich Romane, Mythen und Fantasy-Welten) sind Produkte von Gedankenexperimenten und besitzen keine objektive Realität; zweitens können die Einstellungen fiktiver Welten als Inspirationsquellen und Werkzeuge für Gedankenexperimente verwendet werden, aber nicht direkt als Grundlage der Realität dienen, und müssen die Verifikation und Transformation der realen Gesetze durchlaufen; drittens können Dinge, die in der Realität noch nicht existieren, auf der Grundlage bereits verifizierter objektiver Gesetze vernünftig abgeleitet und geschaffen werden, aber diese Schöpfung muss die Verifikation der Praxis akzeptieren.</p><h2 id="ii-warum-mussen-wir-auf-der-realitat-als-basis-bestehen" tabindex="-1">II. Warum müssen wir auf der Realität als Basis bestehen <a class="header-anchor" href="#ii-warum-mussen-wir-auf-der-realitat-als-basis-bestehen" aria-label="Permalink to &quot;II. Warum müssen wir auf der Realität als Basis bestehen&quot;">​</a></h2><h3 id="_2-1-verhinderung-der-verwirrung-zwischen-fiktion-und-realitat" tabindex="-1">2.1 Verhinderung der Verwirrung zwischen Fiktion und Realität <a class="header-anchor" href="#_2-1-verhinderung-der-verwirrung-zwischen-fiktion-und-realitat" aria-label="Permalink to &quot;2.1 Verhinderung der Verwirrung zwischen Fiktion und Realität&quot;">​</a></h3><p>In einer Kultivierungszivilisation haben die Einstellungen fiktiver Welten oft eine starke Anziehungskraft. Viele Kultivierende beziehen ihre Kultivierungsinspiration aus Romanen, Mythen und Legenden, was an sich normal ist. Aber wenn die Einstellungen fiktiver Welten direkt mit den realen Gesetzen gleichgesetzt werden, führt dies zu schwerwiegenden Problemen: Kultivierung nach fiktiven Einstellungen kann zu Kultivierungsabweichungen führen, die Gestaltung von Institutionen auf der Grundlage fiktiver Einstellungen kann zur Loslösung von der Realität führen, die Behandlung fiktiver Charaktere als reale Idole kann zu geistiger Verwirrung führen. Die primäre Funktion der Position der Realität als Basis besteht darin, die Grenze zwischen Fiktion und Realität klar zu ziehen und die Verwirrung zwischen beiden zu verhindern.</p><h3 id="_2-2-gewahrleistung-der-sicherheit-und-wirksamkeit-der-kultivierungspraxis" tabindex="-1">2.2 Gewährleistung der Sicherheit und Wirksamkeit der Kultivierungspraxis <a class="header-anchor" href="#_2-2-gewahrleistung-der-sicherheit-und-wirksamkeit-der-kultivierungspraxis" aria-label="Permalink to &quot;2.2 Gewährleistung der Sicherheit und Wirksamkeit der Kultivierungspraxis&quot;">​</a></h3><p>Kultivierung ist eine ernsthafte Praxis, die den Ursprung des Lebens und den Betrieb von Energie betrifft, und jede falsche Theorie kann schwerwiegende Folgen haben. Die Kultivierungssysteme fiktiver Welten werden oft von Autoren für die Bedürfnisse der Handlung entworfen und entsprechen möglicherweise nicht den realen Gesetzen des Energiebetriebs und der Evolution des Lebens. Wenn Kultivierende fiktive Einstellungen ohne Unterscheidung nachahmen, wird im leichten Fall die Kultivierung wirkungslos und Zeit verschwendet, im schweren Fall kommt es zu Energiestörungen, Kultivierungsabweichungen und sogar Lebensgefahr. Die Position der Realität als Basis verlangt, dass alle Kultivierungstheorien die Verifikation und Validierung der Realität durchlaufen müssen, um die Sicherheit und Wirksamkeit der Kultivierungspraxis zu gewährleisten.</p><h3 id="_2-3-aufrechterhaltung-des-pragmatismus-der-zivilen-institutionen" tabindex="-1">2.3 Aufrechterhaltung des Pragmatismus der zivilen Institutionen <a class="header-anchor" href="#_2-3-aufrechterhaltung-des-pragmatismus-der-zivilen-institutionen" aria-label="Permalink to &quot;2.3 Aufrechterhaltung des Pragmatismus der zivilen Institutionen&quot;">​</a></h3><p>Der Entwurf ziviler Institutionen muss auf objektiven Faktoren wie realen sozialen Bedingungen, Ressourcensituation und Rassenbeziehungen basieren. Wenn man sich von der Realität löst und Institutionen nur auf der Grundlage schöner Vorstellungen oder fiktiver Einstellungen entwirft, werden die Institutionen zu Luftschlössern und können in der Praxis nicht umgesetzt werden. Die Position der Realität als Basis verlangt, dass alle institutionellen Entwürfe von der Realität ausgehen, die Verifikation der Praxis durchlaufen und entsprechend den Veränderungen der Realität kontinuierlich angepasst und verbessert werden.</p><h3 id="_2-4-bereitstellung-einer-zuverlassigen-methodik-fur-innovation-und-schopfung" tabindex="-1">2.4 Bereitstellung einer zuverlässigen Methodik für Innovation und Schöpfung <a class="header-anchor" href="#_2-4-bereitstellung-einer-zuverlassigen-methodik-fur-innovation-und-schopfung" aria-label="Permalink to &quot;2.4 Bereitstellung einer zuverlässigen Methodik für Innovation und Schöpfung&quot;">​</a></h3><p>Realität als Basis bedeutet nicht, Innovation und Vorstellungskraft einzuschränken, sondern eine zuverlässige Methodik für Innovation und Vorstellungskraft bereitzustellen. Fiktion kann als Inspirationsquelle und Werkzeug für Gedankenexperimente verwendet werden, aber die wahre Schöpfung muss auf einem tiefen Verständnis der realen Gesetze basieren. Dinge, die in der Realität nicht existieren, können geschaffen werden, solange sie den objektiven Gesetzen entsprechen; aber wenn sie die objektiven Gesetze verletzen, kann die Vorstellung, so schön sie auch sein mag, nicht zur Realität werden. Die Position der Realität als Basis verbindet &quot;kühne Vorstellung&quot; mit &quot;vorsichtiger Verifikation&quot; und macht die Innovation auf einer soliden Grundlage.</p><h2 id="iii-grundsatze-fur-den-umgang-mit-dem-verhaltnis-zwischen-fiktion-und-realitat" tabindex="-1">III. Grundsätze für den Umgang mit dem Verhältnis zwischen Fiktion und Realität <a class="header-anchor" href="#iii-grundsatze-fur-den-umgang-mit-dem-verhaltnis-zwischen-fiktion-und-realitat" aria-label="Permalink to &quot;III. Grundsätze für den Umgang mit dem Verhältnis zwischen Fiktion und Realität&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Grundsatz</th><th>Inhalt</th><th>Spezifische Anforderungen</th></tr></thead><tbody><tr><td>Unterscheidungsgrundsatz</td><td>Fiktive Einstellungen und reale Gesetze streng unterscheiden</td><td>Jede Theorie muss klar angeben, ob ihr Ursprung fiktive Inspiration oder reale Verifikation ist</td></tr><tr><td>Absorptionsgrundsatz</td><td>Fiktion kann als Inspirationsquelle und Gedankenexperiment verwendet werden</td><td>Förderung der Inspiration aus Fiktion, aber muss die Transformation der realen Gesetze durchlaufen</td></tr><tr><td>Verifikationsgrundsatz</td><td>Alle Theorien müssen die Verifikation der realen Praxis durchlaufen</td><td>Nicht verifizierte Theorien dürfen nur als Hypothesen verwendet werden, nicht als Grundlage für die Praxisanleitung</td></tr><tr><td>Transformationsgrundsatz</td><td>Fiktive Einstellungen müssen in Formen umgewandelt werden, die den realen Gesetzen entsprechen</td><td>Die Konzepte der Fiktion in der Sprache der realen Energiewissenschaft und Gesetzwissenschaft neu ausdrücken</td></tr><tr><td>Grenzgrundsatz</td><td>Die Rechte und Pflichten der fiktiven Welt erstrecken sich nicht auf die Realität</td><td>Die Gültigkeit von Identitäten, Verträgen und Kausalitäten der fiktiven Welt in der Realität nicht anerkennen</td></tr></tbody></table><h2 id="iv-die-mangel-der-fiktion-werden-durch-die-realitat-erganzt-was-in-der-realitat-nicht-existiert-wird-auf-der-grundlage-der-aktualisierung-der-gesetze-geschaffen" tabindex="-1">IV. &quot;Die Mängel der Fiktion werden durch die Realität ergänzt, was in der Realität nicht existiert, wird auf der Grundlage der Aktualisierung der Gesetze geschaffen&quot; <a class="header-anchor" href="#iv-die-mangel-der-fiktion-werden-durch-die-realitat-erganzt-was-in-der-realitat-nicht-existiert-wird-auf-der-grundlage-der-aktualisierung-der-gesetze-geschaffen" aria-label="Permalink to &quot;IV. &quot;Die Mängel der Fiktion werden durch die Realität ergänzt, was in der Realität nicht existiert, wird auf der Grundlage der Aktualisierung der Gesetze geschaffen&quot;&quot;">​</a></h2><p>Dies ist das zentrale operationsprinzip der Position der Realität als Basis und enthält zwei Aspekte:</p><h3 id="_4-1-die-mangel-der-fiktion-werden-durch-die-realitat-erganzt" tabindex="-1">4.1 Die Mängel der Fiktion werden durch die Realität ergänzt <a class="header-anchor" href="#_4-1-die-mangel-der-fiktion-werden-durch-die-realitat-erganzt" aria-label="Permalink to &quot;4.1 Die Mängel der Fiktion werden durch die Realität ergänzt&quot;">​</a></h3><p>Wenn die aus der fiktiven Welt gewonnenen Inspirationen oder Einstellungen nicht vollständig genug sind, nicht selbstkonsistent sind oder nicht den realen Gesetzen entsprechen, sollten sie mit dem in der Realität bereits verifizierten Wissen und den Gesetzen ergänzt und korrigiert werden. Zum Beispiel kann ein bestimmtes fiktives Kultivierungssystem nur die Einteilung der Ebenen beschreiben, ohne den Mechanismus des Energiebetriebs zu erklären, dann muss die reale Energiekreislauftheorie verwendet werden, um seinen Betriebsmechanismus zu ergänzen; eine bestimmte fiktive Technologie kann das grundlegende Gesetz der Energieerhaltung verletzen, dann müssen die realen Gesetze verwendet werden, um ihre Einstellung zu korrigieren.</p><p>Der Ergänzungsprozess ist nicht einfach das Zusammenfügen von Fiktion und Realität, sondern die Verwendung der realen Gesetze als Gerüst, die Umorganisation der vernünftigen Elemente der Fiktion zu einem selbstkonsistenten theoretischen System, das den realen Gesetzen entspricht.</p><h3 id="_4-2-was-in-der-realitat-nicht-existiert-wird-auf-der-grundlage-der-aktualisierung-der-gesetze-geschaffen" tabindex="-1">4.2 Was in der Realität nicht existiert, wird auf der Grundlage der Aktualisierung der Gesetze geschaffen <a class="header-anchor" href="#_4-2-was-in-der-realitat-nicht-existiert-wird-auf-der-grundlage-der-aktualisierung-der-gesetze-geschaffen" aria-label="Permalink to &quot;4.2 Was in der Realität nicht existiert, wird auf der Grundlage der Aktualisierung der Gesetze geschaffen&quot;">​</a></h3><p>Wenn etwas oder eine Fähigkeit in der Realität noch nicht existiert, aber seine Existenzmöglichkeit auf der Grundlage bereits verifizierter objektiver Gesetze abgeleitet werden kann, kann es auf der Grundlage der Gesetze vernünftig aktualisiert und geschaffen werden. Diese Schöpfung ist keine grundlose Vorstellung, sondern eine logische Erweiterung und technologische Umsetzung auf der Grundlage bestehender Gesetze.</p><p>Zum Beispiel ist die technologische Anwendung der Verdopplungsfrüchte ein typischer Fall von &quot;Schöpfung auf der Grundlage der Aktualisierung der Gesetze&quot;. Die Verdopplungsfrüchte stammten ursprünglich aus der Einstellung fiktiver Werke, aber die Forscher der symbiotischen Zivilisation haben ihren Kernmechanismus (Verdopplungsverstärkung) in der Sprache der realen Energiewissenschaft und Gesetzwissenschaft neu ausgedrückt und auf der Grundlage der Gesetze der Energieverstärkung und der Gesetzresonanz eine technologisch umsetzbare Verdopplungstechnologie entwickelt. Dieser Prozess nutzte die fiktive Inspiration und folgte gleichzeitig streng den realen Gesetzen.</p><p>Die Ergebnisse der Schöpfung müssen die Verifikation der Praxis durchlaufen. Nur Schöpfungen, die in der Realität als wirksam, sicher und stabil verifiziert wurden, können in das formale System der symbiotischen Zivilisation aufgenommen werden.</p><h2 id="v-anwendung-der-realitat-als-basis-in-verschiedenen-bereichen" tabindex="-1">V. Anwendung der Realität als Basis in verschiedenen Bereichen <a class="header-anchor" href="#v-anwendung-der-realitat-als-basis-in-verschiedenen-bereichen" aria-label="Permalink to &quot;V. Anwendung der Realität als Basis in verschiedenen Bereichen&quot;">​</a></h2><h3 id="_5-1-im-kultivierungsbereich" tabindex="-1">5.1 Im Kultivierungsbereich <a class="header-anchor" href="#_5-1-im-kultivierungsbereich" aria-label="Permalink to &quot;5.1 Im Kultivierungsbereich&quot;">​</a></h3><p>Alle Kultivierungssysteme müssen den Prozess der &quot;realen Verifikation&quot; durchlaufen: Von der theoretischen Konstruktion über Experimente im kleinen Maßstab bis hin zur Förderung im großen Maßstab muss jede Phase messbare und reproduzierbare Effektdaten aufweisen. Kultivierungsmethoden, die keine reale Verifikation durchlaufen haben, dürfen nur als &quot;experimentelle Methoden&quot; mit Risikohinweis verwendet werden und nicht als formale Methoden gefördert werden.</p><h3 id="_5-2-im-technologiebereich" tabindex="-1">5.2 Im Technologiebereich <a class="header-anchor" href="#_5-2-im-technologiebereich" aria-label="Permalink to &quot;5.2 Im Technologiebereich&quot;">​</a></h3><p>Alle Gesetzestechnologien müssen den Entwicklungsprozess &quot;theoretisch machbar — experimentelle Verifikation — technologische Umsetzung — Sicherheitsbewertung&quot; befolgen. Die theoretische Grundlage der Technologie muss ein bereits verifiziertes objektives Gesetz sein, die Wirkung der Technologie muss messbare Indikatoren aufweisen, und die Sicherheit der Technologie muss eine strenge Bewertung durchlaufen.</p><h3 id="_5-3-im-bereich-der-sozialen-institutionen" tabindex="-1">5.3 Im Bereich der sozialen Institutionen <a class="header-anchor" href="#_5-3-im-bereich-der-sozialen-institutionen" aria-label="Permalink to &quot;5.3 Im Bereich der sozialen Institutionen&quot;">​</a></h3><p>Alle Entwürfe sozialer Institutionen müssen auf realen sozialen Untersuchungen und Datenanalysen basieren. Große institutionelle Änderungen müssen zuerst im kleinen Maßstab erprobt und nach der Effektbewertung schrittweise gefördert werden. Die Bewertungskriterien für Institutionen müssen messbare reale Indikatoren sein, keine abstrakten Konzepte oder fiktiven Einstellungen.</p><h3 id="_5-4-im-bereich-geschichte-und-archaologie" tabindex="-1">5.4 Im Bereich Geschichte und Archäologie <a class="header-anchor" href="#_5-4-im-bereich-geschichte-und-archaologie" aria-label="Permalink to &quot;5.4 Im Bereich Geschichte und Archäologie&quot;">​</a></h3><p>Die Erforschung historischer Ereignisse und alter Zivilisationen muss auf materiellen Beweisen und überprüfbaren historischen Quellen basieren. Der Inhalt von Legenden und Mythen kann als Gegenstand der Kulturforschung verwendet werden, aber nicht direkt als historische Tatsache anerkannt werden. Die archäologische Arbeit folgt dem Niedrigverschmutzungsplan von &quot;Kopierspiegel + Archäologie an isolierten verschiedenen Orten, nur Rückgabe von Wissen&quot;, und gewährleistet, dass die archäologische Arbeit die historische Realität nicht verändert.</p><h2 id="vi-tiefes-verstandnis-des-konzepts-der-realitat" tabindex="-1">VI. Tiefes Verständnis des Konzepts der &quot;Realität&quot; <a class="header-anchor" href="#vi-tiefes-verstandnis-des-konzepts-der-realitat" aria-label="Permalink to &quot;VI. Tiefes Verständnis des Konzepts der &quot;Realität&quot;&quot;">​</a></h2><p>Insbesondere ist zu beachten, dass die &quot;Realität&quot; in der Position der Realität als Basis kein statisches, geschlossenes Konzept ist, sondern ein dynamisches Konzept, das kontinuierlich verstanden und erweitert wird.</p><p>Erstens dehnt sich der Umfang der Realität mit der Entwicklung der Zivilisation kontinuierlich aus. Phänomene, die in der Vergangenheit als &quot;übernatürlich&quot; galten, wurden mit dem tiefen Verständnis von Energie und Gesetzen in den Umfang der Realität einbezogen. Der Ankermechanismus, die Reisen zwischen Ebenen, die Interaktion von Bewusstseinsdomänen usw. mögen aus der Sicht niedriger Zivilisationen &quot;fiktiv&quot; erscheinen, aber in der Realität hoher Zivilisationen existieren sie objektiv.</p><p>Zweitens vertieft sich das Verständnis der realen Gesetze kontinuierlich. Theorien, die heute als &quot;Gesetze&quot; gelten, können in Zukunft durch tiefere Theorien korrigiert oder ersetzt werden. Die Position der Realität als Basis bedeutet nicht, das bestehende Verständnis starr beizubehalten, sondern die grundlegende Methode von &quot;die Praxis als das einzige Kriterium zur Überprüfung der Wahrheit&quot; festzuhalten und das Verständnis der Realität kontinuierlich zu vertiefen.</p><p>Drittens enthält die Realität unendliche Möglichkeiten. Auf der Grundlage bestehender Gesetze können wir viele noch nicht verwirklichte Möglichkeiten ableiten und durch technologische Mittel in die Realität umsetzen. Realität als Basis bedeutet nicht, die Möglichkeiten einzuschränken, sondern zu gewährleisten, dass die Verwirklichung der Möglichkeiten auf einer zuverlässigen Grundlage steht.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Realität als Basis ist die grundlegende Position der Anker-Symbiotischen Zivilisation und der Ausgangspunkt sowie das Ziel aller Theorien und Praktiken der Zivilisation. Sie verlangt, dass wir sowohl eine offene Vorstellungskraft haben, Inspiration aus Fiktion und Legenden absorbieren, als auch einen strengen pragmatischen Geist haben, alle Inspiration unter die Verifikation der realen Gesetze stellen. Die Mängel der Fiktion werden durch die Realität ergänzt, was in der Realität nicht existiert, wird auf der Grundlage der Aktualisierung der Gesetze geschaffen — dieses Prinzip verbindet organisch Vorstellung und Realität, Inspiration und Gesetze, Schöpfung und Verifikation und bietet eine zuverlässige methodologische Garantie für die kontinuierliche Evolution der symbiotischen Zivilisation.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Gesamtübersicht des Kosmos von Heng Yuan Zhou)</li><li>16-倍增果实技术化原理 (Prinzip der Technologisierung der Verdopplungsfrüchte)</li><li>84-考古协议总纲 (Gesamtprogramm des Archäologieprotokolls)</li></ul>',43)])])}const f=n(s,[["render",a]]);export{c as __pageData,f as default};
